import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.BbQrW5_t.js";const u=JSON.parse('{"title":"代码审计 · Java","description":"","frontmatter":{"title":"代码审计 · Java","date":"2026-09-03T00:00:00.000Z","tags":["网络安全","中级"]},"headers":[],"relativePath":"study/cyber-security/chapters/中级篇/05-代码审计-Java.md","filePath":"study/cyber-security/chapters/中级篇/05-代码审计-Java.md","lastUpdated":1788493831000}'),i={name:"study/cyber-security/chapters/中级篇/05-代码审计-Java.md"};function o(l,a,r,d,p,c){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="_05-·-代码审计-java——20-年功底的变现章" tabindex="-1">05 · 代码审计 Java——20 年功底的变现章 <a class="header-anchor" href="#_05-·-代码审计-java——20-年功底的变现章" aria-label="Permalink to &quot;05 · 代码审计 Java——20 年功底的变现章&quot;">​</a></h1><blockquote><p>别人审计 Java 要先学三个月语言；你直接从&quot;调用链&quot;开打。本章目标：建立<strong>数据流回溯</strong>的方法论 + 吃透反序列化这条最经典的链。</p></blockquote><h2 id="🎯-学习目标" tabindex="-1">🎯 学习目标 <a class="header-anchor" href="#🎯-学习目标" aria-label="Permalink to &quot;🎯 学习目标&quot;">​</a></h2><ol><li>画出 Java 反序列化的调用链原理图</li><li>逐环讲清 CommonsCollections1 链为什么成立</li><li>掌握&quot;路由表→危险函数→回溯&quot;审计工作流</li><li>用补丁 diff 法分析一个历史 CVE</li></ol><h2 id="📖-核心知识" tabindex="-1">📖 核心知识 <a class="header-anchor" href="#📖-核心知识" aria-label="Permalink to &quot;📖 核心知识&quot;">​</a></h2><h3 id="_5-1-反序列化原理-readobject-就是-另一个-eval" tabindex="-1">5.1 反序列化原理：readObject 就是&quot;另一个 eval&quot; <a class="header-anchor" href="#_5-1-反序列化原理-readobject-就是-另一个-eval" aria-label="Permalink to &quot;5.1 反序列化原理：readObject 就是&quot;另一个 eval&quot;&quot;">​</a></h3><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ObjectInputStream ois </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ObjectInputStream</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(inputStream);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Object obj </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ois.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readObject</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← 这行等于把字节流当&quot;代码&quot;执行构造逻辑</span></span></code></pre></div><p>序列化数据 ≠ 数据——<strong>readObject 会执行被恢复对象的 readObject() 方法</strong>。如果 classpath 里存在&quot;readObject 里有危险动作的类链&quot;，攻击者构造的字节流就能触发任意行为。这就是&quot; gadget chain（利用链）&quot;。</p><h3 id="_5-2-commonscollections1-链逐环拆解-教学经典" tabindex="-1">5.2 CommonsCollections1 链逐环拆解（教学经典） <a class="header-anchor" href="#_5-2-commonscollections1-链逐环拆解-教学经典" aria-label="Permalink to &quot;5.2 CommonsCollections1 链逐环拆解（教学经典）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ObjectInputStream.readObject()</span></span>
<span class="line"><span> └─ AnnotationInvocationHandler.readObject()      ← 入口：map 是代理，触发 entrySet()</span></span>
<span class="line"><span>     └─ DynamicProxy → LazyMap.get()              ← 代理转发到 LazyMap</span></span>
<span class="line"><span>         └─ ChainedTransformer.transform()        ← LazyMap.get 缺 key 时触发转换器链</span></span>
<span class="line"><span>             ├─ ConstantTransformer(Runtime.class)      恒定返回 Runtime 类</span></span>
<span class="line"><span>             ├─ InvokerTransformer.getMethod(&quot;getRuntime&quot;)  反射拿方法</span></span>
<span class="line"><span>             ├─ InvokerTransformer.invoke(...)          反射调用 → Runtime 对象</span></span>
<span class="line"><span>             └─ InvokerTransformer.exec(&quot;calc.exe&quot;)     执行命令</span></span></code></pre></div><p>理解三件事：</p><ol><li><strong>InvokerTransformer 是&quot;反射任意调用&quot;的通用积木</strong>（getName/invoke 参数可控）</li><li><strong>ChainedTransformer 把积木串起来</strong>，上一环输出=下一环输入</li><li><strong>入口找一个&quot;readObject 时会自动调用 map.get()&quot;的类</strong>——AnnotationInvocationHandler</li></ol><p>漏洞修复史：CommonsCollections 3.2.2 移除危险序列化支持 → JEP 290 序列化过滤（白名单机制）。<strong>防御答案=过滤+减少 classpath 的 gadget 面</strong>。</p><h3 id="_5-3-spring-struts-的-cve-模式归纳" tabindex="-1">5.3 Spring/Struts 的 CVE 模式归纳 <a class="header-anchor" href="#_5-3-spring-struts-的-cve-模式归纳" aria-label="Permalink to &quot;5.3 Spring/Struts 的 CVE 模式归纳&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>原理</th><th>代表</th></tr></thead><tbody><tr><td>SpEL 注入</td><td>用户输入进 SpEL 表达式上下文</td><td>Spring Data Commons RCE</td></tr><tr><td>OGNL 注入</td><td>Struts 把输入当 OGNL 执行</td><td>S2-045（Content-Type 触发）</td></tr><tr><td>反序列化</td><td>接口直接 readObject</td><td>各类中间件</td></tr><tr><td>路径遍历/下载</td><td>文件名未归一化</td><td>各类 /download?file=</td></tr><tr><td>SSRF/URL 拼接</td><td>服务端请求可控 URL</td><td>各类 webhook 功能</td></tr></tbody></table><h3 id="_5-4-补丁-diff-阅读法-你的天赋区" tabindex="-1">5.4 补丁 diff 阅读法（你的天赋区） <a class="header-anchor" href="#_5-4-补丁-diff-阅读法-你的天赋区" aria-label="Permalink to &quot;5.4 补丁 diff 阅读法（你的天赋区）&quot;">​</a></h3><p>流程：CVE 公告 → GitHub 找 fix commit → 只看 diff 的<strong>语义</strong>：</p><ul><li>新增了 <code>if</code>/校验 → 原代码缺什么检查（这就是漏洞本质）</li><li>类型变化（String→URI）→ 原来的解析被利用了</li><li>加了 try/白名单 → 被绕过的边界在哪</li></ul><p>示例思维：某个 fix 加了 <code>filename.replaceAll(&quot;\\\\.\\\\./&quot;, &quot;&quot;)</code> → 说明原版本路径遍历，且<strong>编码绕过（..%2f）当时没覆盖</strong>——这就是 1-day 的切入点。</p><h3 id="_5-5-审计工作流-从零审一个开源-java-cms" tabindex="-1">5.5 审计工作流（从零审一个开源 Java CMS） <a class="header-anchor" href="#_5-5-审计工作流-从零审一个开源-java-cms" aria-label="Permalink to &quot;5.5 审计工作流（从零审一个开源 Java CMS）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 跑起来：docker/本地启动，抓路由表（Controller @RequestMapping 清单）</span></span>
<span class="line"><span>2. 列危险汇点：</span></span>
<span class="line"><span>   Runtime.exec / ProcessBuilder / JNDI lookup(InitialContext)</span></span>
<span class="line"><span>   readObject / XMLDecoder / SpEL(parseExpression) / JDBC 拼接 / new File(userInput)</span></span>
<span class="line"><span>3. 逐个回溯：汇点参数 ← 谁传入 ← 一路追到 Controller 入参（数据流回溯）</span></span>
<span class="line"><span>4. 可达性判断：有没有权限门槛/编码过滤挡在中间</span></span>
<span class="line"><span>5. 写 PoC（本地复现）→ 审计报告（漏洞+数据流图+修复建议）</span></span></code></pre></div><p>工具辅助：IDEA 的 Find Usages、CodeQL、Grep 危险函数——但<strong>判断&quot;可达性&quot;只能人脑</strong>。</p><h2 id="🔬-动手实操" tabindex="-1">🔬 动手实操 <a class="header-anchor" href="#🔬-动手实操" aria-label="Permalink to &quot;🔬 动手实操&quot;">​</a></h2><ol><li>Maven 起一个带 commons-collections 3.1 的本地靶场，构造 CC1 链打本地（教学复现）</li><li>选一个开源 Java CMS（如若依类）跑通 5.5 流程，产出第一份审计报告</li></ol><h2 id="⚠️-常见坑" tabindex="-1">⚠️ 常见坑 <a class="header-anchor" href="#⚠️-常见坑" aria-label="Permalink to &quot;⚠️ 常见坑&quot;">​</a></h2><ol><li>背链不解链——面试/实战考的是&quot;每环为什么成立&quot;</li><li>只看危险函数不回溯——没有数据流的&quot;危险函数&quot;大多不可达</li><li>忽略 classpath——gadget 存在与否取决于依赖树（<code>mvn dependency:tree</code> 是审计起点）</li><li>JEP 290 等修复机制不学——现代环境绕不过</li><li>审计结论不写 PoC——不可复现的发现等于没有</li></ol><h2 id="✅-自测题" tabindex="-1">✅ 自测题 <a class="header-anchor" href="#✅-自测题" aria-label="Permalink to &quot;✅ 自测题&quot;">​</a></h2><details><summary>1. 为什么说 readObject &quot;等于另一个 eval&quot;？</summary><p>它会执行恢复对象的 readObject() 定义逻辑，攻击者可通过字节流选择&quot;执行哪条已存在于 classpath 的构造链&quot;，数据即代码。</p></details><details><summary>2. CC 链中 InvokerTransformer 的角色？</summary><p>反射任意调用的通用积木：构造时指定 方法名/参数类型/参数值，transform 时对输入对象 invoke——把&quot;字符串描述的方法调用&quot;变成真实执行。</p></details><details><summary>3. JEP 290 防御了什么？</summary><p>序列化过滤：反序列化时按白名单/黑名单校验即将恢复的类，不在名单内直接拒绝——从根上限制 gadget 的可达类集合。</p></details><details><summary>4. 补丁 diff 里看到&quot;新增正则过滤 ..\\.&quot;，推断什么？</summary><p>原版本存在路径遍历且当前只修了字面 ../——结合历史绕过经验可测 URL 编码（..%2f）、双重编码等 1-day 变体。</p></details><details><summary>5. 审计报告里&quot;数据流图&quot;的价值？</summary><p>把&quot;source（用户输入）→ sink（危险函数）&quot;的路径显式化，让修复者精确定位该在哪一层拦（入口校验/汇点白名单），也是漏洞可信度的证明。</p></details><h2 id="🔗-对应周任务与资源" tabindex="-1">🔗 对应周任务与资源 <a class="header-anchor" href="#🔗-对应周任务与资源" aria-label="Permalink to &quot;🔗 对应周任务与资源&quot;">​</a></h2><ul><li><strong>W69-W72</strong>；资源：ysoserial 源码阅读、《Java 代码审计入门》、CodeQL 官方教程</li></ul>`,34)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
